sourcesContent:
```jsx
const AuthCheck = (navigate) => {
    const token = localStorage.getItem("token");

    console.log("Token:", token);

    if (!token) {
        navigate("/login/", { replace: true });
        return false;
    }

    return true;
};

export default AuthCheck;
```
